def is_square(s):
    n = len(s)
    if n % 2 != 0:
        return "NO"
    mid = n // 2
    return "YES" if s[:mid] == s[mid:] else "NO"

def main():
    t = int(input())
    results = []
    for _ in range(t):
        s = input()
        results.append(is_square(s))
    for result in results:
        print(result)

main()
